const PKG = 'docs/release/SD-43-market-inventory-and-abilities'
const ROOT = '/home/ubuntu/workspace/repos/codex'
const byId = Object.fromEntries(CARDS.map(c => [c.id, c]))
const REPAIR = Object.assign({}, A.repair || {})
const SKIP = A.skip || {}       // {cardId: 'why'} — awaiting an operator ruling; not dispatched   // {cardId: 'what the verify step found'} — re-dispatch to fix only that
// run 2: a title regex marked census cards as screen cards; the card section says whether it looks at a screen
const isScreen = (c) => /MC$/.test(c.id) || /screenshot|Looked at|\.tsx|pdftotext|Printout|print block/.test(c.section)

function makeSemaphore(n) {
  let free = n
  const q = []
  const release = () => { free++; if (q.length) { free--; q.shift()(release) } }
  return { acquire: () => new Promise(res => { if (free > 0) { free--; res(release) } else q.push(res) }) }
}
const sem = makeSemaphore(3), hub = makeSemaphore(1)

// one deferred per card up front, so cross-lane dependants can await before the lane reaches the card
const done = {}
for (const c of CARDS) { let r; const p = new Promise(x => { r = x }); done[c.id] = { p, resolve: r } }

const prefix = (c) => PREFIX_RAW.split('<card-id>').join(c.id.toLowerCase())
  .split('<lane>').join(c.lane).split('<run id>').join(RUN)

const RED_SCHEMA = { type: 'object', required: ['exitCode', 'command', 'failingLine', 'secondCallSites', 'diskFreeGb', 'logged'],
  properties: { exitCode: { type: 'integer' }, command: { type: 'string' }, failingLine: { type: 'string' },
    secondCallSites: { type: 'string' }, diskFreeGb: { type: 'number' }, logged: { type: 'boolean' }, note: { type: 'string' } } }
const IMPL_SCHEMA = { type: 'object', required: ['status', 'sha', 'receipt', 'report'],
  properties: { status: { type: 'string', enum: ['complete', 'partial', 'blocked-escalated', 'declined'] },
    sha: { type: 'string' }, receipt: { type: 'string' }, report: { type: 'string' }, lookedAt: { type: 'array', items: { type: 'string' } }, discoveredCards: { type: 'array', items: { type: 'string' } } } }
const VERIFY_SCHEMA = { type: 'object', required: ['ok', 'problems'],
  properties: { ok: { type: 'boolean' }, problems: { type: 'array', items: { type: 'string' } } } }

const cardBlock = (c) => `YOUR CARD: ${c.id} (lane ${c.lane}, tier ${c.tier}, cargo ${c.cargo ? 'yes' : 'no'}, hub ${c.hub ? 'HELD FOR YOU' : 'no'})
kanban.md row:
${c.row}

epic-breakdown.md section (verbatim):
${c.section}
`

function redPrompt(c) {
  return `${prefix(c)}

You are the LEAD'S PRE-DISPATCH RED STEP for card ${c.id} (workflow-instruction.md §2.2 "RED before dispatch").
You do NOT implement anything. Steps, inside your lane tree (make it per the prefix if absent):
1. The prefix's FIRST COMMAND; then \`git fetch origin tranche-43 && git rebase origin/tranche-43\`; \`df -h /\` (report GB free on /).
2. Run the card's acceptance command(s) from its section below on this pre-change tree (for a merge-check / closure /
   census card whose acceptance is a review or a not-yet-written artifact, the RED is the existence check of the
   receipt or artifact the card must create, e.g. \`test -f ${PKG}/artifacts/epic_<n>/${c.id}_cycle_receipt.md\`).
   Capture the exit code and the first failing line. A cargo command obeys the prefix's cargo rules.
3. Second call sites: \`git grep -n\` over every producer / file the card names; summarise the hits (paths:lines).
4. Re-fetch, then append ONE row to ${PKG}/progress.md "## Dispatch log" table:
   | <today> | ${c.id} | ${RUN} | <RED command> | <exit> | <failing line> | <the git grep used> |
   Commit ONLY that file ("docs(sd43): ${c.id} RED logged") and push with workflow-instruction §5 (rebase-retry; never force).
5. Unfiltered \`git status --porcelain\` must print nothing at the end.
Return the structured result. exitCode 0 means the card cannot be dispatched (log it anyway).

${cardBlock(c)}`
}

function implPrompt(c, red) {
  return `${prefix(c)}

PROCEDURE (workflow-instruction.md §6, verbatim — binding):
${PROCEDURE}

${cardBlock(c)}
THE LEAD'S PRE-DISPATCH RED (logged in progress.md Dispatch log):
- command: ${red.command}
- exit: ${red.exitCode}
- failing line: ${red.failingLine}
SECOND CALL SITES (lead's git grep): ${red.secondCallSites}
${c.id === 'E3.1' ? '\nOPERATOR RULING Q-22.3 (2026-11-22): the Feats tab is renamed Abilities; Feats becomes one of its seven sub-tabs (today\'s FeatsTab unchanged in behaviour). No second feat picker, no tab beside Feats.\n' : ''}
RECEIPT AND BOARD (checked by a separate verify step; a miss fails the card):
- The receipt has rows literally named "closure check", "RED", "Does not cover"${isScreen(c) ? ', and "Looked at" naming every image path you Read and what you saw in it' : ''} (receipts.md §2).
- Your kanban.md row's last column holds the receipt path and the literal 40-hex SHA of your work commit (not a command).
- Work in your lane tree as the prefix says; this agent has no isolated worktree.${isScreen(c) ? `
- SCREEN CARD: §6 step 6 is not optional. Launch the app (run-desktop / ui-smoke --keep), save PNGs under
  ${PKG}/artifacts/epic_<n>/${c.id}/, Read each one, and return their repo paths in lookedAt. If an interaction cannot be
  driven (e.g. drag), screenshot the changed screen at rest and say in the receipt what the image cannot show.
  A complete with an empty lookedAt is failed by the script (runs 2-3: E1.2, E1.3, E1.8 skipped this step).` : ''}

Return: status (complete only if the card's Definition of Done is fully met, kanban row set to complete with receipt
path and SHA, and pushed to origin/tranche-43), the pushed SHA, the receipt path, and your §6 step 9 report text.`
}

function verifyPrompt(c, r) {
  const screen = isScreen(c)
  return `Read-only check of card ${c.id}'s claimed result. Do NOT write anything. Never trust the agent's message.
cd ${ROOT} && git fetch origin tranche-43 -q
1. \`git merge-base --is-ancestor ${r.sha || 'MISSING'} origin/tranche-43\` must succeed.
2. \`git show origin/tranche-43:${PKG}/kanban.md | awk -F'|' '$2 ~ /^ ${c.id.replace('.', '\\.')} *$/ {print $5, $10}'\` must show complete, a receipt path, and a literal 40-hex SHA (a command in place of a SHA fails).
3. The receipt \`${r.receipt}\` exists on origin/tranche-43 (\`git show origin/tranche-43:<path>\`). Save it to a temp file and run
   \`grep -c 'closure check\\|Does not cover\\|RED' <file>\` → must be ≥ 3, and each of "closure check", "Does not cover", "RED" occurs at least once.
${screen ? '4. This is a screen card or merge check: the receipt must contain a "Looked at" row that names image paths (they exist on origin/tranche-43) and says what was seen in them.\n' : ''}Return ok=true only if every check passes; list each failed check in problems.`
}

const e4gPrompt = (c) => `${prefix(c)}

You handle the bundle's one OPERATOR WAIT, card E4.G. You never approve names yourself.
In your lane tree ${ROOT}/.worktrees/sd43-lead (create it per the prefix if absent; no cargo, no code):
fetch + rebase origin/tranche-43. Read ${PKG}/progress.md "## Operator replies".
- If a line starting "- E4.G" exists with the operator's reply: return status complete, quoting it.
- Otherwise, if no "E4.G question" block exists yet, append under "## Operator replies" a short block titled
  "E4.G question (waiting)" that asks the operator to (a) approve or edit ${PKG}/artifacts/epic_4/proposed-names.md and
  (b) confirm the reading of "1" (Q-20.1, see decisions.md), and says the lead records the reply as "- E4.G (<date>): <verbatim>".
  Commit only progress.md, push via §5. Return status partial.
${cardBlock(c)}`


const repairPrompt = (c) => `${prefix(c)}

REPAIR of card ${c.id}. Its change is already on origin/tranche-43 and its kanban row says complete, but the lead's
verify step failed it for this reason only:
  ${REPAIR[c.id]}
Fix exactly that, nothing else (no new feature work). If it needs a fresh look at the app, follow §6 step 6 (run-desktop,
isolated XDG_DATA_HOME, Read every PNG, keep images under ${PKG}/artifacts/epic_<n>/${c.id}/). Update the receipt; keep the
kanban row complete with the literal 40-hex SHA of your repair commit; push via §5. Return complete only when fixed and pushed.${isScreen(c) ? ' Screen card: return every image path you Read in lookedAt.' : ''}

${cardBlock(c)}`

// verify a claimed complete; on a miss, one automatic repair agent, then verify again (runs 2-3 needed a manual restart per miss)
async function checkResult(c, r, attempt) {
  let problems = []
  if (isScreen(c) && !(r.lookedAt && r.lookedAt.length)) problems.push('screen card returned no lookedAt image paths (§6 step 6 skipped)')
  else {
    const v = await agent(verifyPrompt(c, r), { model: 'haiku', label: `verify:${c.id}`, phase: c.phase, schema: VERIFY_SCHEMA })
    if (v && v.ok) return { id: c.id, status: 'complete', sha: r.sha, receipt: r.receipt }
    problems = v ? v.problems : ['verify agent died']
  }
  if (attempt >= 1) return { id: c.id, status: 'unverified', sha: r.sha, why: problems.join('; ') }
  log(`${c.id}: verify miss, auto-repair — ${problems.join('; ').slice(0, 200)}`)
  REPAIR[c.id] = problems.join('; ')
  return await repairAndVerify(c, 1)
}
async function repairAndVerify(c, attempt) {
  const r = await agent(repairPrompt(c), { model: c.tier, label: `repair:${c.id}`, phase: c.phase, schema: IMPL_SCHEMA })
  if (!r || r.status !== 'complete') return { id: c.id, status: r ? r.status : 'agent-died', report: r && r.report }
  return await checkResult(c, r, attempt)
}

const notDispatched = (id, why) => ({ id, status: 'not-dispatched', why })

async function runCard(c) {
  if (DONE.has(c.id)) return { id: c.id, status: 'complete', cached: true }
  if (SKIP[c.id]) return notDispatched(c.id, `awaiting operator ruling: ${SKIP[c.id]}`)
  if (c.tier === 'lead') return notDispatched(c.id, 'lead card: the lead marks it complete and passes it in args.done')
  const deps = await Promise.all(c.deps.map(d => done[d].p))
  const bad = deps.filter(r => r.status !== 'complete').map(r => r.id)
  if (bad.length) return notDispatched(c.id, `dependency not complete: ${bad.join(', ')}`)

  if (c.id === 'E4.G') {
    const g = await agent(e4gPrompt(c), { model: 'sonnet', label: 'E4.G operator wait', phase: c.phase, schema: IMPL_SCHEMA })
    return { id: c.id, status: g && g.status === 'complete' ? 'complete' : 'partial', report: g && g.report }
  }

  const rel = []
  try {
    if (c.cargo) rel.push(await sem.acquire())
    if (c.hub) rel.push(await hub.acquire())
    if (REPAIR[c.id]) return await repairAndVerify(c, 1)
    const red = await agent(redPrompt(c), { model: 'sonnet', label: `red:${c.id}`, phase: c.phase, schema: RED_SCHEMA })
    if (!red) return { id: c.id, status: 'red-failed', why: 'RED agent returned nothing' }
    if (red.diskFreeGb < 24) return { id: c.id, status: 'stopped-disk', why: `${red.diskFreeGb} GB free < 24 GB` }
    if (red.exitCode === 0) return { id: c.id, status: 'declined', why: `RED exited 0: ${red.command}` }
    if (!red.logged) return { id: c.id, status: 'red-failed', why: 'RED not logged in progress.md' }
    log(`${c.id}: RED exit ${red.exitCode} — dispatching on ${c.tier}`)
    const r = await agent(implPrompt(c, red), { model: c.tier, label: c.id, phase: c.phase, schema: IMPL_SCHEMA })  // no isolation: run 1 showed worktree isolation blocks the lane tree
    if (!r) return { id: c.id, status: 'agent-died' }
    if (r.status !== 'complete') return { id: c.id, status: r.status, sha: r.sha, report: r.report }
    const out = await checkResult(c, r, 0)
    return out.status === 'complete' ? { ...out, discovered: r.discoveredCards || [] } : out
  } finally { rel.reverse().forEach(f => f()) }
}

async function runLane(name, ids) {
  let stopped = null
  for (const id of ids) {
    const c = byId[id]
    const r = stopped ? notDispatched(id, `lane ${name} stopped at ${stopped}`) : await runCard(c)
    done[id].resolve(r)
    if (r.status !== 'complete' && !stopped) { stopped = id; log(`lane ${name} stops at ${id}: ${r.status} ${r.why || ''}`) }
  }
}

// The lead lane holds C0 (always in DONE) and E4.G; it runs beside the work lanes.
await parallel(Object.entries(LANES).map(([name, ids]) => () => runLane(name, ids)))

const results = await Promise.all(CARDS.map(c => done[c.id].p))
const open = results.filter(r => r.status !== 'complete')
const firstOpen = CARDS.map(c => c.id).find(id => open.some(o => o.id === id))
return {
  runTag: RUN,
  complete: results.filter(r => r.status === 'complete').map(r => r.id),
  open,
  resume: firstOpen ? `START=${firstOpen}; pass done = the complete list above` : 'all 56 complete',
}
